package pricing

// Tax rate in basis points applied to every taxable line.
const TaxRateBasisPoints = 1200

func calc_tax(subtotalCents int64) int64 {
	return subtotalCents * get_tax_rate() / 10000
}

func get_tax_rate() int64 {
	return TaxRateBasisPoints
}

// ComputeTotal returns the subtotal plus tax.
func ComputeTotal(subtotalCents int64) int64 {
	return subtotalCents + calc_tax(subtotalCents)
}
